import React, { useState, useRef, useCallback, useEffect } from 'react';
import Webcam from 'react-webcam';
import { attendanceAPI } from './api_service';

const CameraRecognition = () => {
  const webcamRef = useRef(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [messageType, setMessageType] = useState("info"); // "success" | "error" | "info"
  const [autoMode, setAutoMode] = useState(false);

  const videoConstraints = {
    width: 1280,
    height: 720,
    facingMode: "user"
  };

  const handleCapture = useCallback(async () => {
    if (!webcamRef.current) return;

    setLoading(true);
    setMessage("");
    setMessageType("info");

    try {
      const imageSrc = webcamRef.current.getScreenshot();
      if (!imageSrc) throw new Error("Impossible de capturer l'image");

      const response = await attendanceAPI.recognize(imageSrc);
      const data = response?.data || response || {};

      console.log("🔍 RAW RESPONSE:", response);
      console.log("📊 DATA:", data);

      const studentName = String(data.student || data.student_name || data.name || "Inconnu");
      const confidence = Number(data.confidence || 0) * 100;

      if (data.success || studentName !== "Inconnu") {
        setMessage(`✅ ${studentName} - Confiance: ${confidence.toFixed(1)}%`);
        setMessageType("success");
      } else {
        setMessage(String(data.message || data.error || "Visage non reconnu"));
        setMessageType("error");
      }

    } catch (err) {
      const errorMsg = 
        err.response?.data?.error || 
        err.response?.data?.message || 
        err.message || 
        "Erreur de connexion au serveur";

      console.error("❌ Erreur:", err);
      setMessage(String(errorMsg));
      setMessageType("error");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    let interval = null;
    if (autoMode && !loading) {
      interval = setInterval(handleCapture, 5000);
    }
    return () => clearInterval(interval);
  }, [autoMode, loading, handleCapture]);

  return (
    <div style={{ padding: '30px', maxWidth: '720px', margin: '0 auto' }}>
      <h2 style={{ textAlign: 'center', marginBottom: '25px' }}>📷 Reconnaissance Faciale</h2>

      <div style={{ 
        position: 'relative', 
        borderRadius: '16px', 
        overflow: 'hidden', 
        background: '#000',
        boxShadow: '0 10px 30px rgba(0,0,0,0.3)'
      }}>
        <Webcam
          ref={webcamRef}
          audio={false}
          screenshotFormat="image/jpeg"
          videoConstraints={videoConstraints}
          style={{ width: '100%', height: 'auto', display: 'block' }}
        />

        {loading && (
          <div style={{
            position: 'absolute',
            inset: 0,
            background: 'rgba(0,0,0,0.85)',
            color: 'white',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: '24px',
            fontWeight: 'bold'
          }}>
            ⏳ Analyse en cours...
          </div>
        )}
      </div>

      <div style={{ marginTop: '25px', display: 'flex', gap: '15px' }}>
        <button
          onClick={handleCapture}
          disabled={loading || autoMode}
          style={{
            flex: 1,
            padding: '16px',
            fontSize: '17px',
            background: loading || autoMode ? '#64748b' : '#4F46E5',
            color: 'white',
            border: 'none',
            borderRadius: '10px',
            cursor: loading || autoMode ? 'not-allowed' : 'pointer',
            fontWeight: '600'
          }}
        >
          {loading ? '⏳ Traitement...' : '🔍 Scan Manuel'}
        </button>

        <button
          onClick={() => setAutoMode(!autoMode)}
          style={{
            flex: 1,
            padding: '16px',
            fontSize: '17px',
            background: autoMode ? '#EF4444' : '#10B981',
            color: 'white',
            border: 'none',
            borderRadius: '10px',
            cursor: 'pointer',
            fontWeight: '600'
          }}
        >
          {autoMode ? '⏹ STOP AUTO' : '🔄 AUTO SCAN'}
        </button>
      </div>

      {message && (
        <div style={{
          marginTop: '30px',
          padding: '20px',
          borderRadius: '12px',
          fontSize: '19px',
          fontWeight: '500',
          textAlign: 'center',
          backgroundColor: messageType === 'success' ? '#DCFCE7' : '#FEE2E2',
          color: messageType === 'success' ? '#166534' : '#991B1B',
          border: messageType === 'success' ? '2px solid #86EFAC' : '2px solid #FECACA'
        }}>
          {message}
        </div>
      )}

      {!message && !loading && (
        <p style={{ textAlign: 'center', color: '#64748B', marginTop: '40px' }}>
          Cliquez sur "Scan Manuel" pour tester la reconnaissance faciale
        </p>
      )}
    </div>
  );
};

export default CameraRecognition;
